Translate("deDE", "mount-hyjal", {
	title = "Berg Hyjal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Berg Hyjal ist der heilige Berg der {link:night-elves}Nachtelfen{/link}, der sich im Norden von {link:kalimdor}Kalimdor{/link} jenseits von {link:felwood}Teufelswald{/link} und {link:winterspring}Winterspring{/link} erhebt. Auf seinem Gipfel wächst {link:nordrassil}Nordrassil{/link}, der Weltenbaum. Zehntausend Jahre lang hielten die Kaldorei in seinem Schatten ihre Wacht. Dann kam die {link:burning-legion}Brennende Legion{/link}, und der Berg wurde zum Feld der letzten Schlacht des {link:third-war}Dritten Krieges{/link}.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der neue Brunnen.{/b} Nach der {link:great-sundering}Großen Teilung{/link} goss {link:illidan-stormrage}Illidan Stormrage{/link} gestohlenes Wasser des {link:well-of-eternity}Brunnens der Ewigkeit{/link} in einen See auf dem Berg, und ein zweiter Brunnen entstand.
• {b}Der Weltenbaum.{/b} Die Drachenaspekte ließen {link:nordrassil}Nordrassil{/link} über diesem Brunnen wachsen, um ihn zu versiegeln. Seine Wurzeln tranken aus dem Wasser, und seine Äste beschirmten die schlafenden Druiden.
• {b}Die Schlacht.{/b} Im Dritten Krieg stieg {link:archimonde}Archimonde{/link} den Berg hinauf, um den Brunnen zu leeren. {link:orcs}Orcs{/link}, {link:humans}Menschen{/link} und {link:night-elves}Nachtelfen{/link} verteidigten gemeinsam seine Hänge, und der Dämonenfürst wurde an den Wurzeln des Baumes in der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link} vernichtet.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[{link:archimonde}Archimonde{/link} ist fort, doch der Berg hat ihn nicht vergessen. Seine Hänge tragen noch die Narben jenes Krieges, und das Land beginnt erst jetzt zu heilen. Der Weg hinauf von Norden führt durch die flüsternde Schlucht, wo noch immer Dämonen der Legion verweilen. Auf dem Berg selbst erheben sich unter denen, die geblieben sind, neue Mächte, und jede sucht mitzubestimmen, was aus Hyjal werden soll. Viele, die den Aufstieg wagen, kommen, um das Land wiederherzustellen und Verbündete unter denen zu finden, die es ihre Heimat nennen.]=],
		},
	},
})

Translate("deDE", "hyjal-summit", {
	title = "Hyjal Summit",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hyjal Summit ist die Krone des {link:mount-hyjal}Berges Hyjal{/link}, die Höhe, auf der sich {link:nordrassil}Nordrassil{/link} über den zweiten {link:well-of-eternity}Brunnen der Ewigkeit{/link} erhebt. Nur wenige Orte der Welt wiegen so schwer im Gedächtnis ihrer Völker. Hier pflanzten die {link:night-elves}Nachtelfen{/link} nach der {link:great-sundering}Großen Teilung{/link} ihre Hoffnung, und hier wurde zehntausend Jahre später die {link:burning-legion}Brennende Legion{/link} gebrochen. Nun ist es wieder ein Ort der Gefahr, und nur eine starke Schar kann zu ihm hinaufsteigen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Als {link:illidan-stormrage}Illidan{/link} seinen Brunnen auf dem Berg schuf, zerstörten ihn die Überlebenden des alten Krieges nicht. Stattdessen kamen die Drachenaspekte und setzten einen Samen in sein Wasser. Der Baum, der aus diesem Samen wuchs, versiegelte den Brunnen unter seinen Wurzeln. Nozdormu band das Leben der Kaldorei an ihn, und Ysera band ihn an den {link:emerald-dream}Smaragdgrünen Traum{/link}. Von jenem Tag an war der Gipfel heiliger Boden. Die Druiden von {link:malfurion-stormrage}Malfurion Stormrage{/link} schliefen in seiner Nähe, und die {link:sentinels}Schildwachen{/link} von {link:tyrande-whisperwind}Tyrande Whisperwind{/link} wachten über die Wälder darunter.]=],
		},
		{
			title = "Das letzte Gefecht",
			text = [=[Im {link:third-war}Dritten Krieg{/link} kam {link:archimonde}Archimonde{/link} zum Berg, um die Macht des Brunnens zu trinken und die Welt zu verschlingen. {link:humans}Menschen{/link}, {link:orcs}Orcs{/link} und {link:night-elves}Nachtelfen{/link} stellten sich ihm an den Hängen entgegen, und jedes Volk hielt stand, so lange es konnte, bevor es zurückwich. Als der Dämonenfürst den Gipfel erreichte und den Weltenbaum erklomm, blies {link:malfurion-stormrage}Malfurion{/link} das Horn des {link:cenarius}Cenarius{/link}. Die Geister der Ahnen stürzten sich in Schwärmen auf ihn, und er wurde vernichtet. Der Sieg kostete den Baum seine Macht, und die Nachtelfen verloren ihre Unsterblichkeit. Menschen, Orcs und Nachtelfen hatten Seite an Seite gekämpft, und eine Zeit lang hielten die alten Feinde den Frieden, den sie dort geschlossen hatten. Die ganze Geschichte wird in der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link} erzählt.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Der Gipfel trägt noch immer die Spuren jenes Krieges. {link:nordrassil}Nordrassil{/link} steht versengt und geschwächt über dem Brunnen, den er bewacht. Rings um den Berg versuchen die, die geblieben sind, das Land zu heilen. Doch die Höhen sind nicht in Frieden. Auf dem Gipfel sammelt sich Gefahr, und wer ihr entgegentreten will, muss in großer Zahl und kampfbereit hinaufsteigen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Was Hyjal Summit nun bedroht und wer sich den Helden entgegenstellt, die ihn erklimmen, hat noch keine Chronik dieses Zeitalters niedergeschrieben.]=],
		},
	},
})
